const input = ($json.body && typeof $json.body === 'object') ? $json.body : $json;

const tableId = input.tableId || ($json.headers && ($json.headers['x-teable-table-id'] || $json.headers['X-Teable-Table-Id'])) || ($json.query && $json.query.tableId);
if (!tableId || typeof tableId !== 'string') {
  throw new Error('Missing tableId. Provide it in the JSON body, query string, or x-teable-table-id header.');
}

let rawRecords;
if (Array.isArray(input.records)) {
  rawRecords = input.records;
} else if (input.fields && typeof input.fields === 'object' && !Array.isArray(input.fields)) {
  rawRecords = [{ fields: input.fields }];
} else {
  const fields = { ...input };
  delete fields.tableId;
  delete fields.fieldKeyType;
  delete fields.typecast;
  delete fields.order;
  rawRecords = [{ fields }];
}

if (rawRecords.length === 0) {
  throw new Error('records cannot be empty.');
}

const records = rawRecords.map((record, index) => {
  if (!record || typeof record !== 'object' || Array.isArray(record)) {
    throw new Error(`records[${index}] must be an object.`);
  }
  const fields = (record.fields && typeof record.fields === 'object' && !Array.isArray(record.fields))
    ? record.fields
    : record;
  return { fields };
});

return [{
  json: {
    tableId,
    records,
    fieldKeyType: input.fieldKeyType || 'name',
    typecast: input.typecast !== false,
    ...(input.order ? { order: input.order } : {})
  }
}];
